-- OLDER RENT PLAN FEES (item 7a) — batch acct_corr_202611_legacy_fees. DRAFT, not approved.
--
-- ACCOUNTING RECORDS ONLY. NO MONEY MOVEMENT. Platform-scope journals only: no wallet leg; no Rent Plan, collection or
-- wallet record changes; nothing is deleted. Runs AFTER migration 20261125130000.
--
-- CFO decision 16 Nov 2026: fees of Rent Plans funded before the fee entries began (8 Sep 2026) — absorbed into Legacy
-- Opening Balance Adjustments (E3) by the 22 Sep 2026 restatement — are recognised: collected → revenue (R1), not yet
-- collected → deferred fees (L7), released as tenants repay (nightly job recognise_legacy_plan_fees).
-- Scope: 928 Rent Plans restated on 22 Sep 2026 with a fee (fee = total repayable − rent). Fee collected = amount
-- repaid × fee / total repayable (the same proportional split as today's repayment split). Completed Plans: only the
-- collected fee is recognised; any unpaid remainder stays in E3. Held: 235 Plans not in the restatement (fee 7.2M).
--   G (per Plan, dated 22 Sep 2026 12:00 EAT, the restatement): DR E3 legacy_plan_fee_restated_e3 (UGX 180,767,810) /
--     CR R1 legacy_plan_fee_revenue (collected before then, UGX 128,688,782) / CR L7 legacy_plan_fee_deferred (the rest)
--   H (per Plan and month of collection after 22 Sep): DR L7 / CR R1 (UGX 10,895,220 over 662 Plan-months), dated the
--     last day of the month (16 Nov 2026 for November), in proportion to the Plan's known collections in each month.
--   Left deferred (unpaid on open Plans), released by the nightly job as tenants pay: UGX 41,183,808.
-- Rollback: the same groups with directions swapped (see the end of this file).
begin isolation level repeatable read;

create temp table _expected (n int, e3 numeric, before_rst numeric, after_rst numeric, months int) on commit drop;

-- Rent Plan, fee, total repayable, recognisable fee, fee collected before 22 Sep 2026, fee collected after by month
create temp table _p (rent_request_id uuid primary key, fee numeric not null, total numeric not null, eff numeric not null,
                      before_rst numeric not null, months jsonb not null) on commit drop;
;

do $corr$
declare
  c_batch constant text := 'acct_corr_202611_legacy_fees';
  c_cfo   constant uuid := '29a0cfa8-1eaf-453c-874c-0fc72fa4f74b';
  c_rst   constant timestamptz := '2026-09-22 12:00+03';
  r record; e record; m record; v_n int; v_x numeric; v_grp uuid; v_td timestamptz;
  s_wallet_legs bigint; s_wallet_sum numeric; s_rr text;
begin
  if (select count(*) from public.ledger_account_map where category like 'legacy_plan_fee_%') <> 3
     or to_regclass('public.legacy_plan_fee_schedule') is null then
    raise exception 'STOP: migration 20261125130000 is not installed';
  end if;
  if exists (select 1 from public.accounting_correction_register where batch = c_batch) then
    raise exception 'STOP: batch % is already posted', c_batch;
  end if;
  select * into e from _expected;
  select count(*), coalesce(sum(eff), 0) into v_n, v_x from _p;
  if v_n <> e.n or v_x <> e.e3 or (select sum(before_rst) from _p) <> e.before_rst
     or (select coalesce(sum(v::numeric), 0) from _p, jsonb_each_text(months) x(k, v)) <> e.after_rst then
    raise exception 'STOP: input does not match the approved totals';
  end if;

  -- 1. Every Plan still matches the evidence: same fee and total, restated on 22 Sep, no fee entries of its own,
  --    and what has been collected so far still covers what is recognised as collected.
  for r in select p.*, rr.rent_amount, rr.total_repayment, rr.amount_repaid, rr.status from _p p left join public.rent_requests rr on rr.id = p.rent_request_id loop
    if r.total_repayment is null or r.total_repayment <> r.total or r.total_repayment - r.rent_amount <> r.fee
       or r.eff > r.fee or r.before_rst > r.eff
       or least(r.fee, round(coalesce(r.amount_repaid, 0) * r.fee / r.total)) < r.before_rst + (select coalesce(sum(v::numeric), 0) from jsonb_each_text(r.months) x(k, v))
       or not exists (select 1 from public.general_ledger g where g.category = 'rent_plan_receivable_restatement' and g.source_id = r.rent_request_id)
       or exists (select 1 from public.general_ledger g where g.category in ('fee_receivable_created', 'treasury_fee_recognised') and g.source_id = r.rent_request_id) then
      raise exception 'STOP: Rent Plan % no longer matches the evidence', r.rent_request_id;
    end if;
  end loop;

  -- 2. Money-safety snapshot.
  select count(*), coalesce(sum(amount), 0) into s_wallet_legs, s_wallet_sum from public.general_ledger where ledger_scope = 'wallet';
  select md5(coalesce(string_agg(t::text, '|' order by t.id), '')) into s_rr from public.rent_requests t where t.id in (select rent_request_id from _p);

  -- 3. Schedule, G and H.
  select rent_request_id, fee, total, eff from _p;

  for r in select * from _p order by rent_request_id loop
    v_grp := public.create_ledger_transaction(
      jsonb_build_array(
        jsonb_build_object('ledger_scope', 'platform', 'direction', 'cash_in', 'amount', r.eff, 'category', 'legacy_plan_fee_restated_e3',
          'source_table', 'rent_requests', 'source_id', r.rent_request_id, 'currency', 'UGX', 'classification', 'production', 'transaction_date', c_rst,
          'description', format('Correction (accounting only, no money moved): Rent Plan access fee (UGX %s) absorbed into the 22 Sep 2026 restatement is recognised', r.eff)))
      || case when r.before_rst > 0 then jsonb_build_array(
        jsonb_build_object('ledger_scope', 'platform', 'direction', 'cash_out', 'amount', r.before_rst, 'category', 'legacy_plan_fee_revenue',
          'source_table', 'rent_requests', 'source_id', r.rent_request_id, 'currency', 'UGX', 'classification', 'production', 'transaction_date', c_rst,
          'description', format('Rent Plan access fee collected before 22 Sep 2026 (UGX %s)', r.before_rst))) else '[]'::jsonb end
      || case when r.eff - r.before_rst > 0 then jsonb_build_array(
        jsonb_build_object('ledger_scope', 'platform', 'direction', 'cash_out', 'amount', r.eff - r.before_rst, 'category', 'legacy_plan_fee_deferred',
          'source_table', 'rent_requests', 'source_id', r.rent_request_id, 'currency', 'UGX', 'classification', 'production', 'transaction_date', c_rst,
          'description', format('Rent Plan access fee not yet collected on 22 Sep 2026 (UGX %s): deferred until the tenant pays', r.eff - r.before_rst))) else '[]'::jsonb end,
      c_batch || ':g:' || r.rent_request_id::text, false);
      correction_group_id, amount, before_value, after_value, detail, created_by)
    values (c_batch, 'G', 'legacy_plan_fee_recognised', 'rent_requests', r.rent_request_id, r.rent_request_id, v_grp, r.eff, r.eff, 0,
      jsonb_build_object('fee', r.fee, 'collected_before_restatement', r.before_rst), c_cfo);

    for m in select k, v::numeric amt from jsonb_each_text(r.months) x(k, v) where v::numeric > 0 order by k loop
      v_td := least((date_trunc('month', (m.k || '-01')::date) + interval '1 month' - interval '1 minute')::timestamp at time zone 'Africa/Kampala',
                    '2026-11-16 12:00+03'::timestamptz);
      v_grp := public.create_ledger_transaction(jsonb_build_array(
        jsonb_build_object('ledger_scope', 'platform', 'direction', 'cash_in', 'amount', m.amt, 'category', 'legacy_plan_fee_deferred',
          'source_table', 'rent_requests', 'source_id', r.rent_request_id, 'currency', 'UGX', 'classification', 'production', 'transaction_date', v_td,
          'description', format('Older Rent Plan fee collected in %s (UGX %s): released from deferred fees', m.k, m.amt)),
        jsonb_build_object('ledger_scope', 'platform', 'direction', 'cash_out', 'amount', m.amt, 'category', 'legacy_plan_fee_revenue',
          'source_table', 'rent_requests', 'source_id', r.rent_request_id, 'currency', 'UGX', 'classification', 'production', 'transaction_date', v_td,
          'description', format('Rent Plan access fee earned on repayments in %s (UGX %s)', m.k, m.amt))),
        c_batch || ':h:' || r.rent_request_id::text || ':' || m.k, false);
        correction_group_id, amount, before_value, after_value, detail, created_by)
      values (c_batch, 'H', 'legacy_plan_fee_released_' || m.k, 'rent_requests', r.rent_request_id, r.rent_request_id, v_grp, m.amt, m.amt, 0,
        jsonb_build_object('month', m.k), c_cfo);
    end loop;
  end loop;

  -- 4. Checks.
  select count(*), coalesce(sum(amount), 0) into v_n, v_x from public.accounting_correction_register where batch = c_batch and correction_item = 'G';
  if v_n <> e.n or v_x <> e.e3 then raise exception 'STOP: G posted % / %', v_n, v_x; end if;
  select count(*), coalesce(sum(amount), 0) into v_n, v_x from public.accounting_correction_register where batch = c_batch and correction_item = 'H';
  if v_n <> e.months or v_x <> e.after_rst then raise exception 'STOP: H posted % / %', v_n, v_x; end if;
  if exists (select 1 from public.general_ledger g where g.idempotency_key like c_batch || ':%' and g.ledger_scope <> 'platform') then
    raise exception 'STOP: a correction leg is not platform-scope';
  end if;
  select count(*), coalesce(sum(amount), 0) into v_n, v_x from public.general_ledger where ledger_scope = 'wallet';
  if v_n <> s_wallet_legs or v_x <> s_wallet_sum then raise exception 'STOP: a wallet-scope ledger leg was written'; end if;
  if (select md5(coalesce(string_agg(t::text, '|' order by t.id), '')) from public.rent_requests t where t.id in (select rent_request_id from _p)) <> s_rr then
    raise exception 'STOP: a Rent Plan record changed';
  end if;
  -- repayments made since the schedule was computed are released now by the same rule the nightly job uses
  v_x := (public.recognise_legacy_plan_fees(now()) ->> 'amount')::numeric;
  raise notice 'released for repayments since the schedule: UGX %', v_x;

  values (c_cfo, 'accounting_correction_batch_posted', 'legacy_plan_fees', 'accounting_correction_register', c_batch,
    'Older Rent Plan fees recognised: collected to revenue, unpaid deferred (accounting only)',
    jsonb_build_object('plans', e.n, 'restated', e.e3, 'revenue_before_restatement', e.before_rst, 'released_after', e.after_rst));
  raise notice 'batch % posted: % plans, E3 %, revenue % + %', c_batch, e.n, e.e3, e.before_rst, e.after_rst;
end $corr$;

commit;

-- ROLLBACK (only on CFO instruction): for each register row of this batch, post the same legs with directions swapped,
-- idempotency key acct_corr_202611_legacy_fees:rb:<register id>, dated today; delete the schedule rows; set rolled_back_at.
